{"type":"SearchTool","result_count":3,"content":"{
  "results": [
    {
      "server": "phone",
      "tools": [
        {
          "tool_name": "phone__wait",
          "description": "Wait for the UI to settle, up to 10000 ms.",
          "score": 3.257765531539917,
          "input_schema": {
            "type": "object",
            "properties": {
              "ms": {
                "type": "integer",
                "description": "Milliseconds"
              }
            },
            "required": [
              "ms"
            ]
          }
        },
        {
          "tool_name": "phone__wait_for_install",
          "description": "After opening the Android installer for an APK, wait until the user has tapped Install/Update and confirmed. Returns as soon as the package is installed (at least min_version_code if given), or early if the installer is no longer on screen, or after the timeout. Use this instead of shell polling loops.",
          "score": 2.3126728534698486,
          "input_schema": {
            "type": "object",
            "properties": {
              "package": {
                "type": "string",
                "description": "Package name, e.g. com.buddyapps.flappy"
              },
              "min_version_code": {
                "type": "integer",
                "description": "Wait for at least this versionCode (for updates)"
              },
              "timeout_s": {
                "type": "integer",
                "description": "Default 120, max 300"
              }
            },
            "required": [
              "package"
            ]
          }
        },
        {
          "tool_name": "phone__point_out",
          "description": "Show the user where to look or what to do on the screen: a box, circle or arrow with a short label around up to 6 elements, drawn over the app without blocking their touches. When the user does what a mark points at (taps that button, flips that switch, fills in that field and moves on), it turns green and goes. With wait=true the call returns only then (DONE: what they did) or when they don't (GONE, LEFT, NOT DONE): use it to guide the user step by step through something they want to learn to do themselves, one step per call, instead of doing it for them. Marks follow their element as the screen scrolls, and go when it's gone, when the app changes, when you use another phone action, or after seconds. Call with no marks to remove them.",
          "score": 2.1474292278289795,
          "input_schema": {
            "type": "object",
            "properties": {
              "marks": {
                "type": "array",
                "maxItems": 6,
                "items": {
                  "type": "object",
                  "properties": {
                    "element": {
                      "type": "integer",
                      "description": "Element id from the last read_screen"
                    },
                    "x": {
                      "type": "integer",
                      "description": "Or a point in screen pixels, when read_screen can't see it (from screenshot)"
                    },
                    "y": {
                      "type": "integer",
                      "description": "With x"
                    },
                    "label": {
                      "type": "string",
                      "description": "A few words shown next to it, e.g. \"Your first name\""
                    }
                  }
                },
                "description": "What to point out, e.g. [{\"element\": 12, \"label\": \"First name\"}, {\"element\": 14, \"label\": \"Last name\"}]"
              },
              "style": {
                "type": "string",
                "enum": [
                  "box",
                  "circle",
                  "arrow"
                ]
              },
              "wait": {
                "type": "boolean",
                "description": "Wait until the user has done what the marks point at, or until they can't anymore"
              },
              "seconds": {
                "type": "integer",
                "description": "How long the marks stay at most: default 60 (180 with wait), max 300"
              }
            },
            "required": [
              "marks"
            ]
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 31,
  "status": "ready",
  "note": null
}"}
